<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import ManagementLayout from '@/components/ManagementLayout.vue';import {platformApi,type SchoolClass} from '@/api/platform';const router=useRouter();const items=ref<SchoolClass[]>([]);const loading=ref(true);const error=ref('');async function load(){loading.value=true;error.value='';try{items.value=(await platformApi.classes()).data.items}catch{error.value='班级加载失败，请重试。'}finally{loading.value=false}}onMounted(load)</script>
<template><ManagementLayout><h1>班级列表</h1><p class="muted">当前账号可访问的班级</p><div class="toolbar"><button class="button" @click="load">刷新</button></div><div class="panel"><p v-if="loading">加载中…</p><p v-else-if="error" class="bad">{{error}} <button @click="load">重试</button></p><p v-else-if="!items.length">暂无班级</p><table v-else class="table"><thead><tr><th>班级</th><th>年级</th><th>学年</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{item.name}}</td><td>{{item.grade||'—'}}</td><td>{{item.schoolYear}}</td><td><span class="badge ok">{{item.status}}</span></td><td><button class="button" @click="router.push({name:'students',params:{classId:item.id}})">查看学生</button></td></tr></tbody></table></div></ManagementLayout></template>
